MOD = 1000000007

def parse(line):
    (fields, current) = ([], [])
    state = 'START'
    opening = None
    for (column, char) in enumerate(line, 1):
        if state == 'START':
            if char == ',':
                fields.append('')
            elif char == '"':
                opening = column
                state = 'QUOTED'
            else:
                current.append(char)
                state = 'UNQUOTED'
        elif state == 'UNQUOTED':
            if char == '"':
                return ('ERR', column)
            if char == ',':
                fields.append(''.join(current))
                current = []
                state = 'START'
            else:
                current.append(char)
        elif state == 'QUOTED':
            if char == '"':
                state = 'AFTER_QUOTE'
            else:
                current.append(char)
        elif char == '"':
            current.append('"')
            state = 'QUOTED'
        elif char == ',':
            fields.append(''.join(current))
            current = []
            state = 'START'
        else:
            return ('ERR', column)
    if state == 'QUOTED':
        return ('ERR', opening)
    fields.append(''.join(current))
    return ('OK', fields)

print(parse('a,,"b,c"'))
print(parse('ab"c'))
print(parse('"a"x'))
print(parse('x,"a'))
print(parse(''))
